toolCalls.args:
{"command": "cd /tmp/sv-3dd34a2b1fd741ea89b361b703d6c38e/symbols && \
# Get dynamic symbols sorted by address and look up our offsets
# Offsets: 0x222098, 0x222234, 0x19bac0, 0x19bc14
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | grep -B1 -A0 "$(printf '%016x\n' 0x222098 0x222234 0x19bac0 0x19bc14)" | head -20
echo "==="
# Better approach: find what function contains each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "$addr -> "
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target) }
    { 
      addr_dec = strtonum("0x" $1)
      if (addr_dec <= target_dec) { best = $0; best_addr = addr_dec }
      if (addr_dec > target_dec) { printf "%s (offset +0x%x)\n", best, target_dec - best_addr; exit }
    }
  '
done", "description": "Look up function names from dynamic symbols"}

arguments.command:
cd /tmp/sv-3dd34a2b1fd741ea89b361b703d6c38e/symbols && \
# Get ALL defined dynamic symbols and find nearest for each address
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk '/ [TtWw] / {print}' > dynsyms.txt
wc -l dynsyms.txt
echo "---"
# Find nearest symbol for each address with smaller offset
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo -n "pc $addr -> "
  awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target) }
    { 
      addr_dec = strtonum("0x" $1)
      if (addr_dec <= target_dec) { best_name = $3; best_addr = addr_dec }
      if (addr_dec > target_dec) { printf "%s+0x%x\n", best_name, target_dec - best_addr; found=1; exit }
    }
    END { if (!found) printf "%s+0x%x\n", best_name, target_dec - best_addr }
  ' dynsyms.txt
done

